UPDATE lessons SET title='Year 3, Week 24, Lesson 2: Designing a new game', data=json_patch(data,'{"child_mission":"Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWrite two rules and one adjustment for a new game that uses throwing and catching so that everyone can join in.\n\nFEEDBACK\nRules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.\n\nWATCH FOR\nThinking a good game has the most complicated rules. Simple, clear rules usually work best.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nDesign and write the rules for a new game for 4 to 6 players. Include a name, goal, equipment, space, rules, scoring, safety rules and two adjustments. Play it with family and write down one change after testing.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-MSP-01"],"parent_notes":"Parent: Marking guidance for the independent task: Design and write the rules for a new game for 4 to 6 players. Include a name, goal, equipment, space, rules, scoring, safety rules and two adjustments. Play it with family and write down one change after testing. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original demonstration: Example design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer.\n\nParent: Written model 2: Common error: Thinking a good game has the most complicated rules. Simple, clear rules usually work best. Correction: Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.\n\nParent: Likely misconception: Thinking a good game has the most complicated rules. Simple, clear rules usually work best. Keep sample answers out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise. The other choices avoid explaining the actual strategy.","options":["Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise.","Thinking a good game has the most complicated rules. Simple, clear rules usually work best.","Ignore the safety rule because the first idea looked exciting.","Copy the example and call that independent work."],"question":"Which idea is taught in the stage \"Understand and demonstrate\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others. The other choices avoid explaining the actual strategy.","options":["Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","Writing only a final label without a reason does not show PDHPE thinking.","Copy the example and call that independent work.","Treat a skipped permission or safety step as if it did not matter."],"question":"Which idea is taught in the stage \"Show the reasoning\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice. The other choices avoid explaining the actual strategy.","options":["Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.","Changing the wording without changing the choice does not fix the error. Thinking a good game has the most complicated rules. Simple, clear rules usually work best.","Treat a skipped permission or safety step as if it did not matter.","Leave someone out because the game felt easier that way."],"question":"Which idea is taught in the stage \"Test a misconception\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion. The other choices avoid explaining the actual strategy.","options":["Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.","Repeating the worked example cannot show transfer to a new situation.","Leave someone out because the game felt easier that way.","Ignore the safety rule because the first idea looked exciting."],"question":"Which idea is taught in the stage \"Transfer to a new situation\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive. Useful feedback uses the original cues, rules and reasons.","options":["Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.","Thinking a good game has the most complicated rules. Simple, clear rules usually work best.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Write two rules and one adjustment for a new game that uses throwing and catchin\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\". Useful feedback uses the original cues, rules and reasons.","options":["The most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","Writing only a final label without a reason does not show PDHPE thinking.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"List the key cues, rules or choices from the example and say what each one does \", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive. Useful feedback uses the original cues, rules and reasons.","options":["Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.","Changing the wording without changing the choice does not fix the error. Thinking a good game has the most complicated rules. Simple, clear rules usually work best.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Describe why the warned-against choice does not work, then write a safer, kinder\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The new situation should use the same PDHPE idea as the example, but happen in a different place or with different people. Useful feedback uses the original cues, rules and reasons.","options":["The new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","Repeating the worked example cannot show transfer to a new situation.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Describe or practise one fresh situation that uses the same skill and write a sh\", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Independent evidence, not repetition of the worked model, demonstrates the skill.","marking_guide":"Require independently produced relevant evidence with accurate reasoning and named cues, rules or choices.","question":"Describe or practise a fresh situation that uses the central skill. Name the cues, rules or choices that keep everyone safe and included.","sample_answer":"Original demonstration: Example design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer.","type":"short_answer"},{"explanation":"A correction needs to change the choice or strategy, not just make the answer longer.","marking_guide":"Require an actual misconception plus a corrected choice and a reason linked to safety, health or respect.","question":"Name one likely misconception or unsafe choice for this topic, correct it and say why the correction is safer, healthier or more respectful.","sample_answer":"Common error: Thinking a good game has the most complicated rules. Simple, clear rules usually work best. Correction: Rules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y3-w24-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise designing a game.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Movement Skill and Performance","success_criteria":["I can use designing a game with a specific example from this lesson.","I can identify a game goal and explain why it matters.","I can practise scoring independently on a new prompt.","I can notice adjustments needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise. Supported choices follow the actual cues, rules and purpose of the task.","options":["Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nExample design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer.\n\nTRY FIRST\nWrite two rules and one adjustment for a new game that uses throwing and catching so that everyone can join in.\n\nFEEDBACK\nRules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.","explain":"Designing a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Thinking a good game has the most complicated rules. Simple, clear rules usually work best. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Parts of a game design.","caption":"Include every part.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Design</text><text x=\"28\" y=\"78\">name, goal, rules, scoring</text><text x=\"358\" y=\"42\">Safety</text><text x=\"358\" y=\"78\">no contact, bibs</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball Then write your own reasons."}}]},{"check":{"correct_index":0,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others. Supported choices follow the actual cues, rules and purpose of the task.","options":["Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nExample design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer. Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Adjusting a game for all.","caption":"Adjust so all can play.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Adjust</text><text x=\"28\" y=\"78\">closer hoops</text><text x=\"358\" y=\"42\">Include</text><text x=\"358\" y=\"78\">lighter ball</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice. Supported choices follow the actual cues, rules and purpose of the task.","options":["Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nThinking a good game has the most complicated rules. Simple, clear rules usually work best. Here is a more helpful example: Example design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer.\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nRules: pass before you shoot; no throwing at people. Adjustment: use a lighter ball or shorter distances. These make the game safe, fair and inclusive.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Thinking a good game has the most complicated rules. Simple, clear rules usually work best. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion. Supported choices follow the actual cues, rules and purpose of the task.","options":["Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nDesigning a new game uses what we know about skills, rules, safety, fairness and inclusion. A game design needs a name, a goal, equipment, space, rules, a scoring system, safety rules and a way to adjust the game for different abilities. Test the game, ask for feedback and revise. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 3, Week 24, Lesson 2: Designing a new game","unit_number":5,"unit_title":"Games and sports: teamwork and fair play","week":24,"week_in_unit":4,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample design ''Space Raiders'': 2 teams of 3, soft balls, a 12 by 12 metre area with 4 hoops. Goal: bounce-pass the ball into a hoop. Rules: no contact, three steps with the ball, every player touches the ball. Scoring: 1 point per hoop. Safety: bibs and no running into hoops. Adjustment: hoops can be moved closer.\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Parts of a game design.","caption":"Include every part.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Design</text><text x=\"28\" y=\"78\">name, goal, rules, scoring</text><text x=\"358\" y=\"42\">Safety</text><text x=\"358\" y=\"78\">no contact, bibs</text></g></svg>"},{"alt":"Adjusting a game for all.","caption":"Adjust so all can play.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Adjust</text><text x=\"28\" y=\"78\">closer hoops</text><text x=\"358\" y=\"42\">Include</text><text x=\"358\" y=\"78\">lighter ball</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-pdhpe-y3-w24-l2' AND family_id IS NULL;
